61	// sizeDetails gives the details viewport the room the router leaves it: the
62	// view's width less the two border cells the viewport frame takes, so a line
63	// never reaches under the right border. The padding takes one more cell on each
64	// side, which is the text width (detailsTextWidth).
65	func (m *Model) sizeDetails() {
66		m.detailsViewport.SetWidth(max(m.width-2, 1))
67		m.detailsViewport.SetHeight(m.height)
68	}
69	
70	// detailsTextWidth is how many cells a line of the detail text may span.
71	func (m Model) detailsTextWidth() int { return max(m.width-4, 1) }
72	
73	// scanTarget is the scanned path, for display only: it is what shortPaths cuts
74	// off a path, and an image reference there is ignored.
75	func (m Model) scanTarget() string {
76		if m.result == nil {
77			return ""
78		}
79		return m.result.Target
80	}
81	
82	// targetOnDisk says whether the scanned target is a directory, whose files a
83	// built-in fix can write.
84	func (m Model) targetOnDisk() bool {
85		return m.result != nil && m.result.TargetType == scan.TargetDirectory
86	}
