1	package security
2	
3	import (
4		"strings"
5		"testing"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/remediation"
10		"github.com/anthnel/devdesk/internal/scan"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12	)
13	
14	// DEVDESK-750 (step 3): the fix status line of the finding detail, and the one
15	// computation it shares with the shortcut column (Rule 130).
16	
17	const (
18		labelFixAvailable   = "Fix available"
19		labelNoFixAvailable = "No fix available"
20		labelBuiltIn        = "Built-in fix available"
21		labelDeclined       = "No built-in fix for this instance"
22		labelImage          = "No built-in fix here"
23		labelNoBuiltIn      = "No built-in fix"
24	)
25	
26	func misconfigOf(id string) scan.Finding {
27		return scan.Finding{ID: id, Title: "A misconfiguration", Severity: scan.SeverityHigh,
28			Source: scan.SourceTrivyMisconfig, File: "Dockerfile", Line: 1, EndLine: 3}
29	}
30	
31	func unconfinedSeccomp() scan.Finding {
32		f := misconfigOf("KSV-0104")
33		f.File, f.SeccompOrigin = "pod.yaml", "unconfined"
34		return f
35	}
36	
37	func TestFixStatusOf(t *testing.T) {
38		builtIn, ok := remediation.FixFor(misconfigOf("DS002"))
39		if !ok {
40			t.Fatal("DS002 is no longer in the catalog: pick another built-in rule")
41		}
42		hostNS, ok := remediation.FixFor(misconfigOf("KSV-0009"))
43		if !ok || hostNS.Warning == "" {
44			t.Fatal("KSV-0009 must be a catalog rule with a Warning")
45		}
46		declines := unconfinedSeccomp()
47		declineReason := ""
48		if rule, ok := remediation.FixFor(declines); ok && rule.Declines != nil {
49			declineReason = rule.Declines(declines)
50		}
51		if declineReason == "" {
52			t.Fatal("KSV-0104 unconfined must decline from the finding alone")
53		}
54		missing, ok := remediation.MissingFor(misconfigOf("KSV-0012"))
55		if !ok {
56			t.Fatal("KSV-0012 must have a MissingFor text")
57		}
58	
59		tests := []struct {
60			name       string
61			f          scan.Finding
62			onDisk     bool
63			wantLabel  string
64			wantDetail string
65			wantWarn   string
66		}{
67			{"CVE with a fixed version", scan.Finding{ID: "CVE-1", Source: scan.SourceTrivy, FixedIn: "1.2.3"}, true,
68				labelFixAvailable, "Fixed in 1.2.3", ""},
69			{"CVE on an image with a fixed version", scan.Finding{ID: "CVE-1", Source: scan.SourceTrivy, FixedIn: "1.2.3"}, false,
70				labelFixAvailable, "Fixed in 1.2.3", ""},
71			{"CVE without a fixed version", scan.Finding{ID: "CVE-2", Source: scan.SourceTrivy}, true,
72				labelNoFixAvailable, "No fixed version is published", ""},
73			{"built-in fix on disk", misconfigOf("DS002"), true, labelBuiltIn, builtIn.Title, builtIn.Warning},
74			{"built-in fix with a warning", misconfigOf("KSV-0009"), true, labelBuiltIn, hostNS.Title, hostNS.Warning},
75			{"catalog rule that declines this instance", declines, true, labelDeclined, declineReason, ""},
76			{"catalog rule on an image", misconfigOf("DS002"), false, labelImage, reasonFileNotOnDisk, ""},
77			{"rule with a MissingFor text", misconfigOf("KSV-0012"), true, labelNoBuiltIn, missing, ""},
78			{"rule with no fix and no text", misconfigOf("KSV-0003"), true, labelNoBuiltIn, remediation.ReasonNoFixForRule, ""},
79			{"render failure", scan.Finding{ID: scan.K8sRenderID, Source: scan.SourceKubeconform}, true,
80				labelNoBuiltIn, remediation.ReasonNoFixForRule, ""},
81			{"gitleaks secret", scan.Finding{ID: "generic-api-key", Source: scan.SourceGitleaks}, true, "", "", ""},
82			{"trivy secret", scan.Finding{ID: "aws-access-key-id", Source: scan.SourceTrivySecret}, true, "", "", ""},
83			{"license", scan.Finding{ID: "GPL-3.0", Source: scan.SourceTrivyLicense}, true, "", "", ""},
84			{"CI score", scan.Finding{ID: "PLUMBER-1", Source: scan.SourcePlumber}, true, "", "", ""},
85		}
86		for _, tc := range tests {
87			t.Run(tc.name, func(t *testing.T) {
88				got := fixStatusOf(tc.f, tc.onDisk)
89				want := fixStatus{Label: tc.wantLabel, Detail: tc.wantDetail, Warning: tc.wantWarn}
90				if got != want {
91					t.Errorf("fixStatusOf(%q, onDisk=%v) = %+v, want %+v", tc.f.ID, tc.onDisk, got, want)
92				}
93			})
94		}
95	}
96	
97	// The status carries words, never a key name: the key is the footer's business
98	// (Rules 130 and 134), and one that is greyed would make a hint a lie.
