459	// requireTidy fails on a blank line at either end of the text (the padding's own
460	// blank line is allowed once at each end) and on two blank lines in a row.
461	func requireTidy(t *testing.T, label, content string) {
462		t.Helper()
463		blank := func(s string) bool { return strings.TrimSpace(s) == "" }
464		lines := strings.Split(ansi.Strip(content), "\n")
465		if len(lines) > 0 && blank(lines[0]) {
466			lines = lines[1:]
467		}
468		if len(lines) > 0 && blank(lines[len(lines)-1]) {
469			lines = lines[:len(lines)-1]
470		}
471		if len(lines) == 0 {
472			t.Errorf("%s: the content is empty", label)
473			return
474		}
475		if blank(lines[0]) {
476			t.Errorf("%s: the text starts with a blank line", label)
477		}
478		if blank(lines[len(lines)-1]) {
479			t.Errorf("%s: the text ends with a blank line", label)
480		}
481		for i := 1; i < len(lines); i++ {
482			if blank(lines[i]) && blank(lines[i-1]) {
483				t.Errorf("%s: two blank lines in a row at text line %d:\n%s", label, i, strings.Join(lines, "\n"))
484				return
485			}
486		}
487	}
