			f := hostFinding("KSV-0009", "hostNetwork")
			f.Line, f.EndLine = tt.f.Line, tt.f.EndLine
			if tt.f.Message != "" {
				f.Message = tt.f.Message
			}
			m, dir := hostModel(t, tt.src, f)
			m, cmd := step(t, m, testutil.Key(writeRemediationKey))
