					widest = max(widest, ansi.StringWidth(strings.TrimRight(line, " ")))
				}
				if limit := columnWidth(size.width) + 1; widest > limit {
					t.Errorf("a line spans %d cells, the column plus padding is %d", widest, limit)
				}
			})
